    // ═══════════════ 在想象中学策略（Dreamer 思路的简化版：离散动作 + REINFORCE + λ-return 价值） ═══════════════
    const AC_CFG = { Hh: 64, B: 16, Hi: 15, gamma: 0.95, lambda: 0.95, eta: 0.005, lrA: 1e-3, lrC: 2e-3, tau: 0.02 };
