            let m = -Infinity; for (let j = 0; j < A; j++) m = Math.max(m, z[i * A + j]);
            let s = 0; for (let j = 0; j < A; j++) { const e = Math.exp(z[i * A + j] - m); P[i * A + j] = e; s += e; }
            let H = 0; for (let j = 0; j < A; j++) { const p = (P[i * A + j] /= s); if (p > 0) H -= p * Math.log(p); }
