        const states = new Float32Array((Hi + 1) * B * S), acts = new Int32Array(Hi * B), rews = new Float32Array(Hi * B);
        const h = tmpBuf(tmp, 'ach', B * Hd), z = tmpBuf(tmp, 'acz', B * Z), lg = tmpBuf(tmp, 'aclg', B * NA), at = new Int32Array(B), rr = tmpBuf(tmp, 'acr', B);
        for (let b = 0; b < B; b++) { const k = Math.floor(rand() * rep.n); h.set(rep.Hs.subarray(k * Hd, (k + 1) * Hd), b * Hd); z.set(rep.lat.subarray(k * Z, (k + 1) * Z), b * Z); }
