            real.push(S.val.X.slice((k + 1) * 256, (k + 2) * 256));
            pred.push(P14.decodeFast(S.M.vae, z, 1, new Float32Array(256), tmp)); predM.push(P14.decodeFast(S.M.vae, zm, 1, new Float32Array(256), tmp));
