        for (let t = 0; t < ep.plan.acts.length; t++) { P14.decodeFast(Mp.W.vae, d.zs.subarray(t * 4, t * 4 + 4), 1, img, Mp.tmp); const p = P14.ballPos(img); pts.push(isFinite(p[0]) ? [p[0], p[1]] : null); }
