            const im = P14.decodeFast(W.vae, d.zs.subarray(t * 4, t * 4 + 4), 1, new Float32Array(256), tmp); imag.push(im);
            const q = P14.ballPos(im); ip.push(isFinite(q[0]) ? [q[0], q[1]] : null); if (isFinite(q[0])) pen = Math.max(pen, P14.penetration(q[0], q[1]));
            rImag += d.rs[t];
