        const ni = P.j % PR_N.length, si = Math.floor(P.j / PR_N.length), N = PR_N[ni], W = S.W[S.wm], p = S.starts[si];
        const s = new Float32Array([p[0], p[1], 0, 0]), st = P14.wmStart(W, P14.render(s[0], s[1]));
        const pl = P14.planCEM(W, st, { N, H: R.mpc.H, iters: N > 1 ? 2 : 1, elite: Math.max(1, Math.round(N / 8)), gamma: 1 }, LM.rng(1000 + si), null, P.tmp);
        let re = 0; for (let t = 0; t < R.mpc.H; t++) { P14.envStep(s, pl.acts[t]); re += P14.reward(s[0], s[1]); }
