        const V = frameView(cv, img, { title: which === 'real' ? '真实环境' : `模型的想象（${P.closed ? '闭环：每步同步' : '开环'}）`, foot: which === 'real' ? `t = ${P.steps} · 动作 ${P14.ACT_NAME[P.lastA]}` : `距上次同步 ${P.since} 步 · 位置误差 ${(P.err.length ? P.err[P.err.length - 1][1] : 0).toFixed(2)} px` });
        path(V.ctx, V, which === 'real' ? P.trR : P.trI, which === 'real' ? 'rgba(232,194,90,0.55)' : 'rgba(198,120,221,0.7)', 1.5);
