const P14CPP = {
    common: `
        // ── 本页公用：环境常量、状态结构、几个小工具（与页面 JS 的 P14 逐项相同） ──
        const int IMG = 16, D = IMG * IMG, NA = 5;                   // 16×16 的帧、256 个像素、5 个动作
        const float THRUST = 0.25f, DAMP = 0.8f, REST = 0.5f;        // 推力、每步速度衰减、撞墙恢复系数
        const float BALL_R = 1.0f, DRAW_R = 1.15f;                    // 碰撞半径、绘制半径（像素）
        const float SHADE_GOAL = 0.3f, SHADE_WALL = 0.55f;            // 目标区、墙的灰度（小球 = 1，背景 = 0）

        struct Rect { float x0, y0, x1, y1; };                       // [x0, x1) × [y0, y1)
        struct BallState { float x = 0, y = 0, vx = 0, vy = 0; };     // 真实状态：位置 + 速度（模型看不到，它只看帧）

        const Rect WALLS[5] = { {0, 0, 16, 1}, {0, 15, 16, 16}, {0, 0, 1, 16}, {15, 0, 16, 16}, {7, 1, 9, 10} };   // 四周 + 从上墙垂下的隔墙
        const Rect GOAL = {11, 11, 14, 14};                           // 右下角 3×3 的目标区
        const int DX[NA] = {0, 0, 0, -1, 1}, DY[NA] = {0, -1, 1, 0, 0};   // 不推 / 上 / 下 / 左 / 右（图像坐标 y 向下）

        // 半径 r 的小球放在 (x, y) 会不会和某堵墙重叠
        bool overlapsWall(float x, float y, float r) {
            for (const Rect& w : WALLS)
                if (x + r > w.x0 && x - r < w.x1 && y + r > w.y0 && y - r < w.y1) return true;
            return false;
        }
        bool inGoal(const BallState& s) { return s.x >= GOAL.x0 && s.x < GOAL.x1 && s.y >= GOAL.y0 && s.y < GOAL.y1; }

        // 奖励：离目标中心越近越好（每步 −距离/8）
        float rewardOf(const BallState& s) { return -std::hypot(s.x - 12.5f, s.y - 12.5f) / 8.f; }

        // 动作的 one-hot 行向量 [1 × 5]
        Tensor actionOneHot(int a) { Tensor t = zeros(1, NA); t.v[a] = 1.f; return t; }`,
    env: `
        // 真实环境走一步（原地修改 s）：v ← 0.8·v + 0.25·dir(a)；p ← p + v；
        // 撞墙就停在墙面、该方向速度反向并乘 0.5。先沿 x、再沿 y 移动。返回 1 = 这一步撞了墙
        int envStep(BallState& s, int a) {
            float vx = DAMP * s.vx + THRUST * DX[a], vy = DAMP * s.vy + THRUST * DY[a];
            float x = s.x + vx, y = s.y;
            int bump = 0;
            bool hit = false;
            float lim = vx > 0 ? 1e9f : -1e9f;
            for (const Rect& w : WALLS)
                if (x + BALL_R > w.x0 && x - BALL_R < w.x1 && y + BALL_R > w.y0 && y - BALL_R < w.y1) {
                    hit = true;
                    lim = vx > 0 ? std::min(lim, w.x0 - BALL_R) : std::max(lim, w.x1 + BALL_R);
                }
            if (hit) { x = lim; vx = -REST * vx; bump = 1; }
            y += vy; hit = false; lim = vy > 0 ? 1e9f : -1e9f;
            for (const Rect& w : WALLS)
                if (x + BALL_R > w.x0 && x - BALL_R < w.x1 && y + BALL_R > w.y0 && y - BALL_R < w.y1) {
                    hit = true;
                    lim = vy > 0 ? std::min(lim, w.y0 - BALL_R) : std::max(lim, w.y1 + BALL_R);
                }
            if (hit) { y = lim; vy = -REST * vy; bump = 1; }
            s.x = x; s.y = y; s.vx = vx; s.vy = vy;
            return bump;
        }

        // 把状态画成一帧：背景 0、目标 0.3、墙 0.55、小球 1（每个像素 4×4 超采样，边缘是部分覆盖的灰度）
        std::vector<float> renderFrame(const BallState& s) {
            std::vector<float> img = floats(D);
            for (int j = 0; j < IMG; j++)
                for (int i = 0; i < IMG; i++) {
                    float cx = i + 0.5f, cy = j + 0.5f, v = 0.f;
                    if (cx >= GOAL.x0 && cx < GOAL.x1 && cy >= GOAL.y0 && cy < GOAL.y1) v = SHADE_GOAL;
                    for (const Rect& w : WALLS)
                        if (cx >= w.x0 && cx < w.x1 && cy >= w.y0 && cy < w.y1) v = SHADE_WALL;
                    int cover = 0;
                    for (int sy = 0; sy < 4; sy++)
                        for (int sx = 0; sx < 4; sx++) {
                            float dx = i + (sx + 0.5f) / 4 - s.x, dy = j + (sy + 0.5f) / 4 - s.y;
                            if (dx * dx + dy * dy <= DRAW_R * DRAW_R) cover++;
                        }
                    float c = cover / 16.f;
                    img[j * IMG + i] = v * (1 - c) + c;               // 小球盖在背景上
                }
            return img;
        }`,
    data: `
        // 数据集：nEp 条轨迹 × T 步。frames 的第 e·(T+1) + t 行 = 第 e 条轨迹的第 t 帧
        struct Dataset {
            int nEp = 0, T = 0;
            std::vector<BallState> states;     // 真实状态（只用来画图和评估，模型看不到）
            std::vector<int> actions;          // nEp·T 个动作
            std::vector<float> rewards;        // nEp·(T+1) 个奖励
            Tensor frames;                     // [nEp·(T+1) × 256]
        };

        // 第 k 帧（复制一份）
        std::vector<float> frameAt(const Dataset& ds, int k) {
            std::vector<float> f = floats(D);
            std::copy(ds.frames.v.begin() + (size_t)k * D, ds.frames.v.begin() + (size_t)(k + 1) * D, f.begin());
            return f;
        }

        // 在自由空间里均匀取一个起点（不和墙重叠），静止
        BallState randomFree(Rng& r) {
            for (;;) {
                BallState s;
                s.x = 2 + 12 * (float)uniform(r);
                s.y = 2 + 12 * (float)uniform(r);
                if (!overlapsWall(s.x, s.y, BALL_R)) return s;
            }
        }

        // 随机策略收集经验：动作以 stick = 0.8 的概率沿用上一步（「粘滞」随机，否则小球只会原地抖），否则重新均匀抽
        Dataset collectRandom(int nEp, int T, float stick, Rng& r) {
            Dataset ds;
            ds.nEp = nEp; ds.T = T; ds.frames = zeros(nEp * (T + 1), D);
            for (int e = 0; e < nEp; e++) {
                BallState s = randomFree(r);
                int a = randint(r, NA);
                for (int t = 0; t <= T; t++) {
                    std::vector<float> img = renderFrame(s);
                    std::copy(img.begin(), img.end(), ds.frames.v.begin() + (size_t)(e * (T + 1) + t) * D);
                    ds.states.push_back(s);
                    ds.rewards.push_back(rewardOf(s));
                    if (t == T) break;
                    if (uniform(r) > stick) a = randint(r, NA);
                    ds.actions.push_back(a);
                    envStep(s, a);
                }
            }
            return ds;
        }`,
    vae: `
        // V：VAE。编码器 256 → 64 → (μ, log σ²)，解码器 4 → 64 → 128 → 256（sigmoid）
        struct VAE { Linear e1, e2, d1, d2, d3; int Z = 4; };

        VAE makeVAE(Rng& r) {
            VAE m;
            m.e1 = makeLinear(D, 64, std::sqrt(2.f / D), r);                     // He 初始化（后面接 ReLU）
            m.e2 = makeLinear(64, 2 * m.Z, std::sqrt(2.f / (64 + 2 * m.Z)), r);   // Xavier
            m.d1 = makeLinear(m.Z, 64, std::sqrt(2.f / m.Z), r);
            m.d2 = makeLinear(64, 128, std::sqrt(2.f / 64), r);
            m.d3 = makeLinear(128, D, std::sqrt(2.f / (128 + D)), r);            // Xavier（后面接 sigmoid）
            return m;
        }
        std::vector<Var> vaeParams(const VAE& m) { return { m.e1.W, m.e1.b, m.e2.W, m.e2.b, m.d1.W, m.d1.b, m.d2.W, m.d2.b, m.d3.W, m.d3.b }; }

        // q(z | o) = N(μ, σ²)：X [B × 256] → μ、log σ² [B × Z]
        struct Posterior { Var mu, logvar; };
        Posterior vaeEncode(const VAE& m, const Var& X) {
            Var o = forward(m.e2, relu(forward(m.e1, X)));
            Posterior q;
            q.mu = sliceCols(o, 0, m.Z);
            q.logvar = sliceCols(o, m.Z, 2 * m.Z);
            return q;
        }
        Var vaeDecode(const VAE& m, const Var& z) { return sigmoid(forward(m.d3, relu(forward(m.d2, relu(forward(m.d1, z)))))); }

        // L = recW·Σ‖ô − o‖² + β·KL(N(μ, σ²) ‖ N(0, I))，按 batch 平均
        Var vaeLoss(const VAE& m, const Var& X, float recW, float beta, Rng& r) {
            int B = X->val.rows;
            Posterior q = vaeEncode(m, X);
            Var eps = constant(randn(B, m.Z, 1.f, r));
            Var z = add(q.mu, mul(expAct(scale(q.logvar, 0.5f)), eps));                     // 重参数化 z = μ + σ·ε
            Var rec = scale(mse(vaeDecode(m, z), X), (float)D * recW);                       // mse 是均值：× 256 = 每帧的 Σ
            Var kl = scale(sumAll(sub(add(square(q.mu), expAct(q.logvar)), addConst(q.logvar, 1.f))), 0.5f / B);
            return add(rec, scale(kl, beta));
        }

        // 训练：每步从数据集里随机抽 32 帧，AdamW（lr 3e-3，不做权重衰减），默认 6000 步
        void trainVAE(VAE& m, const Dataset& ds, int steps, float beta, Rng& r) {
            std::vector<Var> ps = vaeParams(m);
            std::vector<bool> decay;
            decay.assign(ps.size(), false);
            AdamW opt = makeAdamW(ps, decay, 3e-3f, 0.f, 0.9f, 0.99f);
            int nF = ds.frames.rows, B = 32;
            for (int it = 0; it < steps; it++) {
                Tensor X = zeros(B, D);
                for (int b = 0; b < B; b++) {
                    int k = randint(r, nF);
                    std::copy(ds.frames.v.begin() + (size_t)k * D, ds.frames.v.begin() + (size_t)(k + 1) * D, X.v.begin() + (size_t)b * D);
                }
                Var loss = vaeLoss(m, constant(X), 25.f, beta, r);
                zeroGrad(ps);
                backward(loss);
                adamwStep(opt, 3e-3f);
            }
        }`,
    dyn: `
        // M：GRU 动力学 + 奖励头。h_t = GRU(h_{t−1}, [z_t, onehot(a_t)])，ẑ_{t+1} = z_t + W_o·h_t + b_o，r̂ = R(z)
        struct GRU { Var Wx, bx, Wh, bh; int H = 32; };
        struct Dynamics { GRU gru; Linear head, r1, r2; int Z = 4; };

        Dynamics makeDynamics(Rng& r) {
            Dynamics m;
            int In = m.Z + NA, H = m.gru.H;
            m.gru.Wx = param(randn(In, 3 * H, std::sqrt(2.f / (In + H)), r));
            m.gru.bx = param(zeros(1, 3 * H));
            m.gru.Wh = param(randn(H, 3 * H, 1.f / std::sqrt((float)H), r));
            m.gru.bh = param(zeros(1, 3 * H));
            m.head = makeLinear(H, m.Z, 0.01f, r);                               // 初始几乎预测「不动」
            m.r1 = makeLinear(m.Z, 32, std::sqrt(2.f / m.Z), r);
            m.r2 = makeLinear(32, 1, 0.05f, r);
            return m;
        }
        std::vector<Var> dynParams(const Dynamics& m) { return { m.gru.Wx, m.gru.bx, m.gru.Wh, m.gru.bh, m.head.W, m.head.b, m.r1.W, m.r1.b, m.r2.W, m.r2.b }; }

        // 一步 GRU：门的顺序与 PyTorch nn.GRUCell 相同（r 重置门、u 更新门、n 候选状态）
        Var gruCell(const GRU& g, const Var& x, const Var& h) {
            int H = g.H;
            Var gx = linear(x, g.Wx, g.bx), gh = linear(h, g.Wh, g.bh);                         // [B × 3H]
            Var r = sigmoid(add(sliceCols(gx, 0, H), sliceCols(gh, 0, H)));
            Var u = sigmoid(add(sliceCols(gx, H, 2 * H), sliceCols(gh, H, 2 * H)));
            Var n = tanhAct(add(sliceCols(gx, 2 * H, 3 * H), mul(r, sliceCols(gh, 2 * H, 3 * H))));
            return add(n, mul(u, sub(h, n)));                                                 // h' = (1 − u)·n + u·h
        }
        Var rewardHead(const Dynamics& m, const Var& z) { return forward(m.r2, relu(forward(m.r1, z))); }

        // 一批潜变量序列：z[t]、act[t]（one-hot）、rew[t]，t = 0..L，每个都是 [B × …]
        struct SeqBatch { int B = 0, L = 0; std::vector<Tensor> z, act, rew; };

        // lat = 整个数据集的 μ(o)（[帧数 × Z]，由冻结的 V 编码）；随机取 B 段长 L+1 的子序列
        SeqBatch sampleSeq(const Dataset& ds, const Tensor& lat, int B, int L, Rng& r) {
            SeqBatch b;
            b.B = B; b.L = L;
            int Z = lat.cols;
            std::vector<int> e = ints(B), t0 = ints(B);
            for (int i = 0; i < B; i++) { e[i] = randint(r, ds.nEp); t0[i] = randint(r, ds.T - L + 1); }
            for (int t = 0; t <= L; t++) {
                Tensor z = zeros(B, Z), a = zeros(B, NA), rw = zeros(B, 1);
                for (int i = 0; i < B; i++) {
                    int k = e[i] * (ds.T + 1) + t0[i] + t;
                    for (int j = 0; j < Z; j++) z.at(i, j) = lat.at(k, j);
                    rw.at(i, 0) = ds.rewards[k];
                    if (t < L) a.at(i, ds.actions[e[i] * ds.T + t0[i] + t]) = 1.f;
                }
                b.z.push_back(z); b.act.push_back(a); b.rew.push_back(rw);
            }
            return b;
        }

        // 沿序列展开 L 步。multiStep：前 warm 步输入真实 z，之后输入自己上一步的预测（梯度穿过预测，学会对自己的误差稳健）
        Var dynLoss(const Dynamics& m, const SeqBatch& b, bool multiStep, int warm) {
            Var h = constant(zeros(b.B, m.gru.H)), zin = constant(b.z[0]), loss;
            for (int t = 0; t < b.L; t++) {
                h = gruCell(m.gru, concatCols(zin, constant(b.act[t])), h);
                Var zp = add(zin, forward(m.head, h));                                         // ẑ_{t+1} = z_t + Δ
                Var zt = constant(b.z[t + 1]);
                Var l = add(mse(zp, zt), mse(rewardHead(m, zt), constant(b.rew[t + 1])));      // 潜变量 + 奖励
                loss = t == 0 ? l : add(loss, l);
                zin = (multiStep && t + 1 >= warm) ? zp : zt;
            }
            return scale(loss, 1.f / b.L);
        }

        void trainDynamics(Dynamics& m, const Dataset& ds, const Tensor& lat, int steps, bool multiStep, Rng& r) {
            std::vector<Var> ps = dynParams(m);
            std::vector<bool> decay;
            decay.assign(ps.size(), false);
            AdamW opt = makeAdamW(ps, decay, 3e-3f, 0.f, 0.9f, 0.99f);
            for (int it = 0; it < steps; it++) {
                SeqBatch b = sampleSeq(ds, lat, 16, 16, r);
                Var loss = dynLoss(m, b, multiStep, 4);
                zeroGrad(ps);
                backward(loss);
                clipGradNorm(ps, 10.f);
                adamwStep(opt, 3e-3f);
            }
        }`,
    imagine: `
        // 模型状态：h = GRU 的记忆 [1 × H]，z = 当前帧的潜变量 [1 × Z]
        struct ModelState { Tensor h, z; };

        // 推理（不记 tape）：一帧 → μ(o)；z → 解码出的一帧
        Tensor encodeMu(const VAE& v, const std::vector<float>& frame) {
            NoGrad ng;
            return vaeEncode(v, constant(fromVector(1, D, frame))).mu->val;
        }
        std::vector<float> decodeFrame(const VAE& v, const Tensor& z) {
            NoGrad ng;
            return vaeDecode(v, constant(z))->val.v;
        }
        ModelState startState(const VAE& v, const Dynamics& m, const std::vector<float>& frame) {
            ModelState st;
            st.h = zeros(1, m.gru.H);
            st.z = encodeMu(v, frame);
            return st;
        }
        // 闭环：真实环境执行了 a、给出新帧 → h 吸收 (z, a)，z 换成新帧的编码（滤波 / 后验）
        void observe(const VAE& v, const Dynamics& m, ModelState& st, int a, const std::vector<float>& frame) {
            NoGrad ng;
            st.h = gruCell(m.gru, concatCols(constant(st.z), constant(actionOneHot(a))), constant(st.h))->val;
            st.z = encodeMu(v, frame);
        }
        // 开环：只在想象里走一步（先验）
        void dream(const Dynamics& m, ModelState& st, int a) {
            NoGrad ng;
            Var h = gruCell(m.gru, concatCols(constant(st.z), constant(actionOneHot(a))), constant(st.h));
            st.z = add(constant(st.z), forward(m.head, h))->val;
            st.h = h->val;
        }
        // 第 e 条轨迹：先用前 k 帧真实观测同步，然后只喂动作想象 K 步。返回想象出的帧 [K × 256]
        Tensor imagineOpenLoop(const VAE& v, const Dynamics& m, const Dataset& ds, int e, int k, int K) {
            int T1 = ds.T + 1;
            ModelState st = startState(v, m, frameAt(ds, e * T1));
            for (int t = 1; t < k; t++) observe(v, m, st, ds.actions[e * ds.T + t - 1], frameAt(ds, e * T1 + t));
            Tensor out = zeros(K, D);
            for (int j = 0; j < K; j++) {
                dream(m, st, ds.actions[e * ds.T + k - 1 + j]);                             // 从这里开始再也不看真实帧
                std::vector<float> img = decodeFrame(v, st.z);
                std::copy(img.begin(), img.end(), out.v.begin() + (size_t)j * D);
            }
            return out;
        }`,
    plan: `
        // 从状态 st 出发，在模型里并行想象 N 条长 H 的动作序列（acts[t·N + i]），按预测奖励的折扣和打分——不解码任何像素
        std::vector<float> scoreSequences(const Dynamics& m, const ModelState& st, const std::vector<int>& acts, int N, int H, float gamma) {
            NoGrad ng;
            Tensor h = zeros(N, m.gru.H), z = zeros(N, m.Z);
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < m.gru.H; j++) h.at(i, j) = st.h.v[j];
                for (int j = 0; j < m.Z; j++) z.at(i, j) = st.z.v[j];
            }
            std::vector<float> ret = floats(N);
            float disc = 1.f;
            for (int t = 0; t < H; t++) {
                Tensor a = zeros(N, NA);
                for (int i = 0; i < N; i++) a.at(i, acts[t * N + i]) = 1.f;
                Var hv = gruCell(m.gru, concatCols(constant(z), constant(a)), constant(h));
                Var zv = add(constant(z), forward(m.head, hv));
                Tensor rr = rewardHead(m, zv)->val;
                for (int i = 0; i < N; i++) ret[i] += disc * rr.v[i];
                h = hv->val; z = zv->val; disc *= gamma;
            }
            return ret;
        }

        // CEM：每个时间步一个动作分布 P[t]。每轮按 P 采样 N 条序列，取前 elite 名，P[t] ← 精英里各动作的比例（混 10% 均匀）
        // （页面里的 JS 还把上一步的最优序列左移一位，当作第一轮的一个候选：MPC 常用的热启动）
        std::vector<int> planCEM(const Dynamics& m, const ModelState& st, int N, int H, int iters, int elite, float gamma, Rng& r) {
            std::vector<float> P = floats(H * NA, 1.f / NA);
            std::vector<int> best = ints(H), acts = ints(H * N);
            float bestRet = -1e30f;
            for (int it = 0; it < iters; it++) {
                for (int t = 0; t < H; t++)
                    for (int i = 0; i < N; i++) {
                        if (i == 0 && it > 0) { acts[t * N] = best[t]; continue; }              // 保留上一轮的最优
                        std::vector<float> p = floats(NA);
                        for (int q = 0; q < NA; q++) p[q] = P[t * NA + q];
                        acts[t * N + i] = sampleIndex(p, r);
                    }
                std::vector<float> ret = scoreSequences(m, st, acts, N, H, gamma);
                std::vector<int> order = ints(N);
                for (int i = 0; i < N; i++) order[i] = i;
                std::sort(order.begin(), order.end(), [&](int a, int b) { return ret[a] > ret[b]; });
                if (ret[order[0]] > bestRet) {
                    bestRet = ret[order[0]];
                    for (int t = 0; t < H; t++) best[t] = acts[t * N + order[0]];
                }
                std::fill(P.begin(), P.end(), 0.f);
                for (int k = 0; k < elite; k++)
                    for (int t = 0; t < H; t++) P[t * NA + acts[t * N + order[k]]] += 1.f / elite;
                for (float& p : P) p = 0.9f * p + 0.1f / NA;
            }
            return best;
        }

        // MPC：每一步都重新规划、只执行计划的第一个动作，看到真实新帧后更新模型状态。返回是否在 Tmax 步内到达目标
        bool mpcEpisode(const VAE& v, const Dynamics& m, BallState s, int Tmax, Rng& r) {
            ModelState st = startState(v, m, renderFrame(s));
            for (int t = 0; t < Tmax; t++) {
                std::vector<int> plan = planCEM(m, st, 32, 12, 2, 8, 0.97f, r);   // N = 32，H = 12，2 轮
                int a = plan[0];
                envStep(s, a);
                observe(v, m, st, a, renderFrame(s));
                if (inGoal(s)) return true;
            }
            return false;
        }`,
    ac: `
        // actor π(a | s) 与 critic v(s)：输入都是模型状态 s = [h, z]（32 + 4 维）
        struct ActorCritic { Linear a1, a2, c1, c2; };
        ActorCritic makeActorCritic(int S, Rng& r) {
            ActorCritic ac;
            ac.a1 = makeLinear(S, 64, std::sqrt(2.f / S), r); ac.a2 = makeLinear(64, NA, 0.01f, r);
            ac.c1 = makeLinear(S, 64, std::sqrt(2.f / S), r); ac.c2 = makeLinear(64, 1, 0.01f, r);
            return ac;
        }
        Var actorLogits(const ActorCritic& ac, const Var& s) { return forward(ac.a2, relu(forward(ac.a1, s))); }
        Var criticValue(const ActorCritic& ac, const Var& s) { return forward(ac.c2, relu(forward(ac.c1, s))); }

        // 策略梯度（自定义算子）：mean_i[ −A_i·log π(a_i|s_i) − η·H(π(·|s_i)) ]
        // ∂/∂z_ij = ( A_i·(p_ij − [j = a_i]) + η·p_ij·(log p_ij + H_i) ) / n
        Var policyLoss(const Var& L, const std::vector<int>& acts, const std::vector<float>& adv, float eta) {
            int n = L->val.rows, A = L->val.cols;
            Tensor P = zeros(n, A);
            std::vector<float> Hs = floats(n);
            double tot = 0;
            for (int i = 0; i < n; i++) {
                std::vector<float> p = floats(A);
                for (int j = 0; j < A; j++) p[j] = L->val.at(i, j);
                softmaxInPlace(p, 1.f);
                for (int j = 0; j < A; j++) { P.at(i, j) = p[j]; if (p[j] > 0) Hs[i] -= p[j] * std::log(p[j]); }
                tot += -adv[i] * std::log(std::max(1e-12f, p[acts[i]])) - eta * Hs[i];
            }
            Tensor y = zeros(1, 1);
            y.v[0] = (float)(tot / n);
            return record(std::move(y), {L}, [L, P, Hs, acts, adv, eta, n, A](Node& o) {
                Tensor& g = gradOf(L);
                float k = o.grad.v[0] / n;
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < A; j++) {
                        float p = P.at(i, j);
                        g.at(i, j) += k * (adv[i] * (p - (j == acts[i] ? 1.f : 0.f)) + eta * p * (std::log(std::max(1e-12f, p)) + Hs[i]));
                    }
            });
        }

        // 一次更新：从回放里的 B 个模型状态出发，用 actor 在 M 里想象 Hi 步（不求梯度）→ λ-return → 更新 critic 与 actor
        // （页面里的 JS 用 critic 参数的指数滑动平均来算引导值，更稳）
        void acUpdate(ActorCritic& ac, AdamW& optA, AdamW& optC, const Dynamics& m, const Tensor& start, int Hi, float gamma, float lambda, float eta, Rng& r) {
            int B = start.rows, S = start.cols, H = m.gru.H;
            std::vector<Tensor> states;
            std::vector<int> acts;
            std::vector<float> rews;
            Tensor s = start;
            {
                NoGrad ng;
                for (int t = 0; t < Hi; t++) {
                    states.push_back(s);
                    Tensor lg = actorLogits(ac, constant(s))->val, oh = zeros(B, NA);
                    for (int b = 0; b < B; b++) {
                        std::vector<float> p = floats(NA);
                        for (int j = 0; j < NA; j++) p[j] = lg.at(b, j);
                        softmaxInPlace(p, 1.f);
                        int a = sampleIndex(p, r);
                        acts.push_back(a); oh.at(b, a) = 1.f;
                    }
                    Var hz = constant(s), h = sliceCols(hz, 0, H), z = sliceCols(hz, H, S);
                    Var h2 = gruCell(m.gru, concatCols(z, constant(oh)), h);                     // 在模型里走一步
                    Var z2 = add(z, forward(m.head, h2));
                    Tensor rr = rewardHead(m, z2)->val;
                    for (int b = 0; b < B; b++) rews.push_back(rr.v[b]);
                    s = concatCols(h2, z2)->val;
                }
                states.push_back(s);
            }
            // λ-return：V_t = r_{t+1} + γ[(1 − λ)·v(s_{t+1}) + λ·V_{t+1}]，V_Hi = v(s_Hi)
            std::vector<float> vals = floats((Hi + 1) * B), ret = floats(Hi * B);
            {
                NoGrad ng;
                for (int t = 0; t <= Hi; t++) {
                    Tensor v = criticValue(ac, constant(states[t]))->val;
                    for (int b = 0; b < B; b++) vals[t * B + b] = v.v[b];
                }
            }
            for (int b = 0; b < B; b++) {
                float G = vals[Hi * B + b];
                for (int t = Hi - 1; t >= 0; t--) { G = rews[t * B + b] + gamma * ((1 - lambda) * vals[(t + 1) * B + b] + lambda * G); ret[t * B + b] = G; }
            }
            Tensor X = zeros(Hi * B, S);
            for (int t = 0; t < Hi; t++) std::copy(states[t].v.begin(), states[t].v.end(), X.v.begin() + (size_t)t * B * S);
            // critic：回归 λ-return
            std::vector<Var> pc = { ac.c1.W, ac.c1.b, ac.c2.W, ac.c2.b };
            Var v = criticValue(ac, constant(X));
            Var lc = mse(v, constant(fromVector(Hi * B, 1, ret)));
            zeroGrad(pc); backward(lc); clipGradNorm(pc, 10.f); adamwStep(optC, 2e-3f);
            // actor：优势 A = V^λ − v(s)，在 batch 内标准化
            std::vector<float> adv = floats(Hi * B);
            double mu = 0, sd = 0;
            for (int i = 0; i < Hi * B; i++) { adv[i] = ret[i] - v->val.v[i]; mu += adv[i] / (Hi * B); }
            for (int i = 0; i < Hi * B; i++) sd += (adv[i] - mu) * (adv[i] - mu) / (Hi * B);
            for (int i = 0; i < Hi * B; i++) adv[i] = (float)((adv[i] - mu) / (std::sqrt(sd) + 1e-4));
            std::vector<Var> pa = { ac.a1.W, ac.a1.b, ac.a2.W, ac.a2.b };
            Var la = policyLoss(actorLogits(ac, constant(X)), acts, adv, eta);
            zeroGrad(pa); backward(la); clipGradNorm(pa, 10.f); adamwStep(optA, 1e-3f);
        }`,
    exploit: `
        // 集成打分：K 个动力学模型（不同随机种子）各想象一遍；得分 = 平均预测回报 − κ·Σ_t（成员间 ẑ 的标准差，各维平均）
        std::vector<float> ensembleScore(const std::vector<Dynamics>& ens, const std::vector<ModelState>& sts, const std::vector<int>& acts, int N, int H, float gamma, float kappa) {
            NoGrad ng;
            int K = (int)ens.size(), Z = ens[0].Z;
            std::vector<float> score = floats(N), zs = floats(K * H * N * Z);
            for (int k = 0; k < K; k++) {
                const Dynamics& m = ens[k];
                Tensor h = zeros(N, m.gru.H), z = zeros(N, Z);
                for (int i = 0; i < N; i++) {
                    for (int j = 0; j < m.gru.H; j++) h.at(i, j) = sts[k].h.v[j];               // 每个成员有自己的记忆 h_k
                    for (int j = 0; j < Z; j++) z.at(i, j) = sts[k].z.v[j];
                }
                float disc = 1.f;
                for (int t = 0; t < H; t++) {
                    Tensor a = zeros(N, NA);
                    for (int i = 0; i < N; i++) a.at(i, acts[t * N + i]) = 1.f;
                    Var hv = gruCell(m.gru, concatCols(constant(z), constant(a)), constant(h));
                    Var zv = add(constant(z), forward(m.head, hv));
                    Tensor rr = rewardHead(m, zv)->val;
                    h = hv->val; z = zv->val;
                    for (int i = 0; i < N; i++) {
                        score[i] += disc * rr.v[i] / K;
                        for (int j = 0; j < Z; j++) zs[((k * H + t) * N + i) * Z + j] = z.at(i, j);
                    }
                    disc *= gamma;
                }
            }
            for (int t = 0; t < H; t++)
                for (int i = 0; i < N; i++) {
                    float u = 0;
                    for (int j = 0; j < Z; j++) {
                        double s1 = 0, s2 = 0;
                        for (int k = 0; k < K; k++) { double x = zs[((k * H + t) * N + i) * Z + j]; s1 += x; s2 += x * x; }
                        u += (float)std::sqrt(std::max(0.0, s2 / K - (s1 / K) * (s1 / K)));
                    }
                    score[i] -= kappa * u / Z;                                                    // 成员们意见不一 = 模型没把握
                }
            return score;
        }

        Dataset mergeData(const Dataset& a, const Dataset& b);   // 两个数据集首尾相接（实现略：逐个字段 insert）

        // 让规划器自己收集数据（ε 概率随机动作）：它会把小球带到模型「以为能走通」的地方，正是模型该补课的地方
        Dataset collectWithPlanner(const VAE& v, const Dynamics& m, int nEp, int T, float eps, Rng& r) {
            Dataset ds;
            ds.nEp = nEp; ds.T = T; ds.frames = zeros(nEp * (T + 1), D);
            for (int e = 0; e < nEp; e++) {
                BallState s = randomFree(r);
                ModelState st = startState(v, m, renderFrame(s));
                for (int t = 0; t <= T; t++) {
                    std::vector<float> img = renderFrame(s);
                    std::copy(img.begin(), img.end(), ds.frames.v.begin() + (size_t)(e * (T + 1) + t) * D);
                    ds.states.push_back(s);
                    ds.rewards.push_back(rewardOf(s));
                    if (t == T) break;
                    int a = uniform(r) < eps ? randint(r, NA) : planCEM(m, st, 32, 12, 2, 8, 0.97f, r)[0];
                    ds.actions.push_back(a);
                    envStep(s, a);
                    observe(v, m, st, a, renderFrame(s));
                }
            }
            return ds;
        }`,
    play: `
        int readArrowKey();                        // 读方向键：−1 = 没按键，0 空格 1 ↑ 2 ↓ 3 ← 4 →（平台代码略）
        bool syncPressed();                        // 这一帧有没有按「同步」（平台代码略）
        void showFrames(const std::vector<float>& real, const std::vector<float>& imagined);   // 把两帧并排画出来（略）

        // playground：同一个按键同时驱动真实环境和模型的想象。filt 一直吸收真实帧（后验），imag 只靠模型（先验）
        void playLoop(const VAE& v, const Dynamics& m, BallState s, bool closedLoop) {
            ModelState filt = startState(v, m, renderFrame(s));
            ModelState imag = filt;
            for (;;) {
                int a = readArrowKey();
                if (a < 0) continue;
                envStep(s, a);
                std::vector<float> real = renderFrame(s);
                observe(v, m, filt, a, real);
                dream(m, imag, a);
                if (closedLoop || syncPressed()) imag = filt;      // 同步 = 把真实帧重新编码进模型状态
                showFrames(real, decodeFrame(v, imag.z));
            }
        }`,
    lib: `
        // 解码帧里小球的位置：减掉静态背景后的亮度加权质心（只用来把模型的想象「读」成坐标、做评估；模型本身不知道坐标）
        struct Point { float x = 0, y = 0; bool ok = false; };
        Point ballPos(const std::vector<float>& img, const std::vector<float>& background) {
            double sx = 0, sy = 0, sw = 0;
            for (int j = 0; j < IMG; j++)
                for (int i = 0; i < IMG; i++) {
                    double w = img[j * IMG + i] - background[j * IMG + i];
                    if (w > 0.05) { sx += w * (i + 0.5); sy += w * (j + 0.5); sw += w; }
                }
            Point p;
            if (sw > 0.3) { p.x = (float)(sx / sw); p.y = (float)(sy / sw); p.ok = true; }
            return p;
        }
        // 小球（半径 BALL_R）陷进墙里多深：0 = 物理上可能的位置
        float penetration(float x, float y) {
            float d = 0;
            for (const Rect& w : WALLS)
                if (x + BALL_R > w.x0 && x - BALL_R < w.x1 && y + BALL_R > w.y0 && y - BALL_R < w.y1)
                    d = std::max(d, std::min(std::min(x + BALL_R - w.x0, w.x1 - (x - BALL_R)), std::min(y + BALL_R - w.y0, w.y1 - (y - BALL_R))));
            return d;
        }`,
};

