                        P14V.label(ctx, '动作 a_t', L.labW - 5, L.top + L.s + 6, { align: 'right', color: '#56b6c2', bg: false }); P14V.label(ctx, '速度 |v|', L.labW - 5, L.top + L.s + 21, { align: 'right', color: LM.C.dim, bg: false });
