                        ctx.strokeStyle = LM.C.green; ctx.setLineDash([4, 3]); ctx.lineWidth = 1.5; ctx.strokeRect(X(11), Y(11), X(14) - X(11), Y(14) - Y(11)); ctx.setLineDash([]);
